    home_win = sum(h_probs[h] * sum(a_probs[a] for a in range(h)) for h in range(max_g + 1))
    away_win = sum(a_probs[a] * sum(h_probs[h] for h in range(a)) for a in range(max_g + 1))
    draw = sum(h_probs[g] * a_probs[g] for g in range(max_g + 1))
    
    total = home_win + away_win + draw
    if total > 0:
        home_win /= total
        away_win /= total
        draw /= total
    
    best_hg, best_ag, best_p = 0, 0, 0
    for hg in range(max_g + 1):
        for ag in range(max_g + 1):
            p = h_probs[hg] * a_probs[ag]
            if p > best_p:
                best_p, best_hg, best_ag = p, hg, ag
    
    fair_home = round(1 / home_win, 2) if home_win > 0 else 99.0
    fair_draw = round(1 / draw, 2) if draw > 0 else 99.0
    fair_away = round(1 / away_win, 2) if away_win > 0 else 99.0
    
    outcomes = [("Home Win", home_win, fair_home), ("Draw", draw, fair_draw), ("Away Win", away_win, fair_away)]
    sel_name, sel_prob, sel_fair = max(outcomes, key=lambda x: x[1])
    confidence = round(sel_prob * 100)
    
    margin = 0.065 if confidence > 65 else 0.095 if confidence > 50 else 0.13
    market_odds = round(sel_fair * (1 + margin), 2)
    
    ev_pct = round(((market_odds / sel_fair) - 1) * 100, 1)
    ev_str = f"+{ev_pct}%" if ev_pct >= 0 else f"{ev_pct}%"
    
    bankroll = 1000
    b = market_odds - 1
    if b > 0 and sel_prob < 1:
        kelly_f = (b * sel_prob - (1 - sel_prob)) / b
        kelly_f = max(0, kelly_f)
        stake_amount = round(bankroll * kelly_f * 0.25, 2)
    else:
        stake_amount = 0.00
    stake_str = f"£{stake_amount} (0.25 Kelly)" if stake_amount > 0 else "—"
    
    btts_yes = round((1 - h_probs[0]) * (1 - a_probs[0]) * 100)
    
    return {
        "home_xg": round(home_xg, 2),
        "away_xg": round(away_xg, 2),
        "home_win_pct": round(home_win * 100),
        "draw_pct": round(draw * 100),
        "away_win_pct": round(away_win * 100),
        "hg": best_hg,
        "ag": best_ag,
        "selection": sel_name,
        "confidence": f"{confidence}%",
        "fair_odds": sel_fair,
        "market_odds": market_odds,
        "ev_value": ev_pct,
        "ev": ev_str,
        "stake": stake_str,
        "btts_probability": btts_yes
    }
